// A custom hook to track the consistency of gesture detection
const useConsistentGesture = (currentGesture, requiredConsistency = 10, handLandmark_for_update, shouldUseGesture, isStreaming) => {
    const [consistentGesture, setConsistentGesture] = useState(null);
    const lastGestureRef = useRef(null);
    const gestureCountRef = useRef({});
  
    useEffect(() => {
      if (shouldUseGesture && isStreaming) {
          if (handLandmark_for_update && currentGesture) {
              if (currentGesture === lastGestureRef.current) {
                  if(gestureCountRef.current[currentGesture]>=12) {
                      // Limit count to 12
                      gestureCountRef.current[currentGesture]=12

                  } else{
                      // Increment count for the current gesture
                      gestureCountRef.current[currentGesture] = (gestureCountRef.current[currentGesture] || 0) + 1;
                      
                  }
                  // console.log(`Current count for gesture "${currentGesture}": ${gestureCountRef.current[currentGesture]}`);
              } else {
                  // Reset the count for the previous gesture and initialize for the new gesture
                  gestureCountRef.current[lastGestureRef.current] = 0;
                  gestureCountRef.current[currentGesture] = 1;
                  // console.log(`Initializing count for gesture "${currentGesture}".`);
              }

              // Check if the current gesture has reached required consistency
              if (gestureCountRef.current[currentGesture] >= requiredConsistency) {
                  // console.log(`Gesture "${currentGesture}" reached required consistency.`);
                  setConsistentGesture(currentGesture);
                  
              }

              // Update the lastGestureRef
              lastGestureRef.current = currentGesture;
          } else {
              // If there are no landmarks detected, reset everything
              gestureCountRef.current = {};
              setConsistentGesture(null);
          }
      } else {
        // If the condition is not met, reset the state
        setConsistentGesture(null);
      }
    }, [currentGesture, handLandmark_for_update, requiredConsistency, shouldUseGesture]);

    // useEffect(() => {
        // console.log('Consistent gesture detected:', consistentGesture);
    // }, [consistentGesture]);

    const resetGestureCount = () => {
        gestureCountRef.current = {};
        // console.log('Count was reset.');
        setConsistentGesture(null);
    };

    return [consistentGesture, resetGestureCount];
  };
  


// Simple custom shader
const AuroraShaderMaterial = shaderMaterial(
  {
    color: new THREE.Color(0.2, 0.5, 1),
    intensity: 1.0 // Default intensity
  },
  // Vertex Shader
  `void main() {
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }`,
  // Fragment Shader
  `uniform vec3 color;
   uniform float intensity;
   void main() {
     gl_FragColor = vec4(color * intensity, 1.0); // Multiply color by intensity
   }`
);
extend({ AuroraShaderMaterial });
  
  
export const ParticleSphereCreation = ({ particleCount = 1000, radius = 5, innerParticleCount = 500, consistentGestureName, handLandmark_12 /* , sphereCameraRef */ }) => {
    const meshRef = useRef();
    const auroraLightRef = useRef();


    const handLightRef = useRef();
    const moonPositionRef = useRef(new THREE.Vector3(0, 0, 0));
    const [showMoon, setShowMoon] = useState(false);
    const moonMeshRef = useRef(); 

    const [leftClickAnim, setLeftClickAnim] = useState(false);



    useEffect(() => {
      handLightRef.current = new THREE.PointLight(0xffffff, 100000, 1);
      handLightRef.current.visible = false;
    }, []);

    const previousLandmarkPositionMORef = useRef({ x: 0, y: 0, z: 0, initialized: false });

    



    



    
  
    // Particles for the perfect sphere
    const outerParticles = useMemo(() => {
      const temp = [];
      const goldenRatio = (1 + Math.sqrt(5)) / 2;
      const angleIncrement = Math.PI * 2 * goldenRatio;
  
      for (let i = 0; i < particleCount; i++) {
        const t = i / particleCount;
        const inclination = Math.acos(1 - 2 * t);
        const azimuth = angleIncrement * i;
  
        const x = radius * Math.sin(inclination) * Math.cos(azimuth);
        const y = radius * Math.sin(inclination) * Math.sin(azimuth);
        const z = radius * Math.cos(inclination);
  
        temp.push([x, y, z]);
      }
      return temp;
    }, [particleCount, radius]);
  
    // Particles for the random distribution inside the sphere
    const innerParticles = useMemo(() => {
      const temp = [];
      for (let i = 0; i < innerParticleCount; i++) {
        const theta = Math.random() * 2 * Math.PI;
        const phi = Math.acos(2 * Math.random() - 1);
        const r = radius * Math.cbrt(Math.random());
  
        const x = r * Math.sin(phi) * Math.cos(theta);
        const y = r * Math.sin(phi) * Math.sin(theta);
        const z = r * Math.cos(phi);
  
        temp.push([x, y, z]);
      }
      return temp;
    }, [innerParticleCount, radius]);
  
    // useMemo hook to maintain the instance of DreiOrbitControls
    //const DreiOrbitControlsMemo = useMemo(() => (
      //<DreiOrbitControls camera={sphereCameraRef.current} enableZoom={true} enablePan={true} enableRotate={true} />
    //), [sphereCameraRef]);


    // Define state to store the previous position of the landmark
    const previousLandmarkPositionRef = useRef({ x: 0, y: 0 });
    // Define state to store the positions for smoothing
    const positionHistoryRef = useRef([]);

    const [isVibrating, setIsVibrating] = useState(false);
    const vibrationRef = useRef({ count: 0, maxCount: 3, direction: 1 });

    const flashlightAngle = Math.PI / 32; // Narrower angle for a more focused light beam
    const flashlightPenumbra = 0.1; // Adjust as needed for softer edges


    const lastPositionRef = useRef(new THREE.Vector3(0, 0, 0)); // This ref will store the last position

    useFrame(() => {
      if (meshRef.current) {
        const movementScale = 0.05; // Adjust this scale to control the sensitivity
        const lerpFactor = 0.1; // Adjust this value for speed of resetting (0.1 for smoother transition)
        

        switch(consistentGestureName) {
          case 'Zoom':
            // console.log("Zooming");
            meshRef.current.position.z += movementScale;
            break;
          case 'Dezoom':
            // console.log("Dezooming");
            meshRef.current.position.z -= movementScale;
            break;
          case 'Bas':
            // console.log("Moving Down");
            meshRef.current.position.y += movementScale;
            break;
          case 'Haut':
            // console.log("Moving Up");
            meshRef.current.position.y -= movementScale;
            break;
          case 'Parfait':
            // console.log("Smoothly Resetting Position");
            // Interpolating towards the origin (0, 0, 0)
            meshRef.current.position.lerp(new THREE.Vector3(0, 0, 0), lerpFactor);
            break;
          // Add other cases as needed
        }
    
        // Drag&Drop
        if (consistentGestureName === 'Drag&Drop' && handLandmark_12) {
          const landmark = handLandmark_12; // Landmark number 12
    
          if (landmark) {
            // Initialize previous position on first detection
            if (!previousLandmarkPositionRef.current.initialized) {
              previousLandmarkPositionRef.current.x = landmark.x;
              previousLandmarkPositionRef.current.y = landmark.y;
              previousLandmarkPositionRef.current.initialized = true; // Mark as initialized
            }

            // Add current position to history
            positionHistoryRef.current.push({ x: landmark.x, y: landmark.y });
    
            // Keep only the last N positions for smoothing
            const smoothingFrames = 10; // Adjust this number to control the smoothness
            if (positionHistoryRef.current.length > smoothingFrames) {
              positionHistoryRef.current.shift();
            }
    
            // Calculate average position
            let averageX = 0, averageY = 0;
            positionHistoryRef.current.forEach(pos => {
              averageX += pos.x;
              averageY += pos.y;
            });
            averageX /= positionHistoryRef.current.length;
            averageY /= positionHistoryRef.current.length;
    
            // Calculate delta
            const deltaX = averageX - previousLandmarkPositionRef.current.x;
            const deltaY = averageY - previousLandmarkPositionRef.current.y;
    
            // Apply rotation with smoothing
            const rotationSensitivity = 1; // Adjust for more or less sensitivity
            meshRef.current.rotation.y += deltaX * rotationSensitivity;
            meshRef.current.rotation.x -= deltaY * rotationSensitivity; // Inverted Y-axis movement
    
            // Update previous position
            previousLandmarkPositionRef.current = { x: averageX, y: averageY };
          }
        } else {
          // Reset history and previous position if gesture is not 'Drag&Drop'
          positionHistoryRef.current = [];
          previousLandmarkPositionRef.current = { x: 0, y: 0 };
        }
    
    
        if (consistentGestureName === 'Poing_Ferme' && !isVibrating) {
          // Start vibrating effect
          setIsVibrating(true);
          vibrationRef.current = { count: 0, maxCount: 3, direction: 1 };
        }
    
        if (isVibrating) {
          // Apply vibration effect
          const vibrationStrength = 0.05;
          const vibrationSpeed = 0.005;
          const maxLightIntensity = 2.0; // Set the desired maximum light intensity

    
          meshRef.current.scale.x += vibrationSpeed * vibrationRef.current.direction;
          meshRef.current.scale.y += vibrationSpeed * vibrationRef.current.direction;
          meshRef.current.scale.z += vibrationSpeed * vibrationRef.current.direction;

          // Adjust light intensity based on scale
          if (auroraLightRef.current) {
            const scaleRatio = (meshRef.current.scale.x - 1) / vibrationStrength;
            auroraLightRef.current.intensity = 0.5 + scaleRatio * (maxLightIntensity - 0.5);
          }
    
          // Switch direction or prepare to stop vibrating
          if (vibrationRef.current.direction === 1 && meshRef.current.scale.x > 1 + vibrationStrength) {
            vibrationRef.current.direction = -1;
          } else if (vibrationRef.current.direction === -1 && meshRef.current.scale.x < 1 - vibrationStrength) {
            vibrationRef.current.direction = 1;
            vibrationRef.current.count++;
          }
    
          // Initiate smooth transition back to original scale
          if (vibrationRef.current.count >= vibrationRef.current.maxCount) {
            const scaleLerpFactor = 0.1; // Control the speed of scale transition
            meshRef.current.scale.lerp(new THREE.Vector3(1, 1, 1), scaleLerpFactor);
    
            // Check if the scale is close enough to the original scale to stop vibrating
            if (Math.abs(meshRef.current.scale.x - 1) < 0.01) {
              setIsVibrating(false);
              meshRef.current.scale.set(1, 1, 1); // Ensure scale is set to exactly 1
            }

            
            // Transition back to original light intensity
            if (!isVibrating) {
              if (auroraLightRef.current) {
                auroraLightRef.current.intensity = THREE.MathUtils.lerp(
                  auroraLightRef.current.intensity,
                  0.5, // Original intensity
                  scaleLerpFactor
                );
              }
            }

          }
        }


        // Clamp the position to prevent excessive movement
        meshRef.current.position.z = Math.max(Math.min(meshRef.current.position.z, 4), -10);
        meshRef.current.position.y = Math.max(Math.min(meshRef.current.position.y, 4), -4);
      }
    
      // Update the rotation of the mesh
      if (meshRef.current && consistentGestureName !== 'Drag&Drop' && consistentGestureName !== 'Main_Ouverte') {
        meshRef.current.rotation.x += 0.001;
        meshRef.current.rotation.y += 0.001;
      }


      
      if (consistentGestureName === 'Main_Ouverte' && handLandmark_12) {
        const landmark = handLandmark_12; // Assuming index 12 is the correct landmark

        // Smoothly reset meshRef's rotation to its original state on detection of 'Main_Ouverte'
        const originalRotation = new THREE.Quaternion(); // Default is (0, 0, 0, 1), which represents no rotation
        const rotationResetSpeed = 0.1; // Control how quickly the rotation resets (0 to 1 range)
        meshRef.current.quaternion.slerp(originalRotation, rotationResetSpeed);
    
        if (!previousLandmarkPositionMORef.current.initialized) {
          // Only set to the origin on the very first detection, otherwise use last known position
          if (lastPositionRef.current.equals(new THREE.Vector3(0, 0, 0))) {
            moonPositionRef.current.set(0, 0, 0);
            handLightRef.current.position.set(0, 0, 0);
          } else {
            moonPositionRef.current.copy(lastPositionRef.current);
            handLightRef.current.position.copy(lastPositionRef.current);
          }
          
          previousLandmarkPositionMORef.current.initialized = true;
        } else {
          // Calculate deltas for movement
          const deltaX = (landmark.x - previousLandmarkPositionMORef.current.x);
          const deltaY = (landmark.y - previousLandmarkPositionMORef.current.y);
          const deltaZ = (landmark.z - previousLandmarkPositionMORef.current.z);
    
          // Update positions based on deltas
          const scaleFactor = -10;
          const zScaleFactor = 10;
          moonPositionRef.current.x += deltaX * scaleFactor;
          moonPositionRef.current.y += deltaY * scaleFactor;
          moonPositionRef.current.z += deltaZ * zScaleFactor;
          handLightRef.current.position.copy(moonPositionRef.current);
    
          // Update the moon mesh's position if it's supposed to be shown
          if (showMoon && moonMeshRef.current) {
            moonMeshRef.current.position.copy(moonPositionRef.current);
          }
        }
    
        // Update previous landmark position
        previousLandmarkPositionMORef.current.x = landmark.x;
        previousLandmarkPositionMORef.current.y = landmark.y;
        previousLandmarkPositionMORef.current.z = landmark.z;
    
        setShowMoon(true);
        handLightRef.current.visible = true;
    
        // Save last known position when 'Main_Ouverte' is active
        lastPositionRef.current.copy(moonPositionRef.current);
      } else {
        // Hide the moon and handlight when 'Main_Ouverte' is not detected
        setShowMoon(false);
        handLightRef.current.visible = false;
        // Do not reset the initialized flag to keep the last known position in memory
        // previousLandmarkPositionMORef.current.initialized = false; // Remove this line
      }

    });
  
    
    

    // Function to get color based on gesture
    // const getShaderColor = () => {
        // switch (consistentGestureName) {
          //case 'Main_Ouverte': return new THREE.Color(0.2, 0.5, 1); // Example color for gesture1
          // case 'Pointe_du_Doigt': return new THREE.Color(0, 1, 0); // Example color for gesture2
          // Add more cases as needed
          // default: return new THREE.Color(1, 0, 0); // Default color
        // }
    // };
  


    // Update leftClickAnim and shader color when Pointe_du_Doigt gesture is detected
    useEffect(() => {
      if (consistentGestureName === 'Right_Click3') {
        setLeftClickAnim(prev => !prev); // Toggle the state
      }
    }, [consistentGestureName]);

    // Function to determine shader color based on leftClickAnim state
    const getShaderColor = () => {
      return leftClickAnim ? new THREE.Color(127/255, 0, 255) : new THREE.Color(1, 0, 0);
    };

    // Use useMemo to avoid recalculating the color unnecessarily
    const shaderColor = useMemo(getShaderColor, [leftClickAnim]);





    return (
      <>
        {/* {DreiOrbitControlsMemo} */}
        <group ref={meshRef}>
          {/* Inner glowing sphere with custom shader */}
          <mesh position={[0, 0, 0]}>
            <sphereGeometry args={[0.5, 32, 32]}/>
            <auroraShaderMaterial color={shaderColor} />
            <pointLight position={[5, 0, 0]} intensity={0.3} color="white" /> 
          </mesh>
          {/* Light source for the glowing effect of centeric sphere */}
          <pointLight ref={auroraLightRef} position={[0, 0, 0]} intensity={0.5} color={shaderColor} />


          {/* Hand position light */}
          {handLightRef.current && (
            <primitive object={handLightRef.current} />
          )}


          {showMoon && (
            <Sphere ref={moonMeshRef} args={[0.5, 32, 32]} position={moonPositionRef.current}>
              <meshPhongMaterial color="white" emissive="white" emissiveIntensity={0.5} />
            </Sphere>
        
          )}
          
    
          {/* Inner point light */}
          {/* <pointLight position={[10, 10, 0]} intensity={0.05} color="White" /> */}
    
          {outerParticles.map((particle, i) => (
            <mesh key={`outer-${i}`} position={particle}>
              <sphereGeometry args={[0.1, 16, 16]} />
              <meshStandardMaterial 
              color="teal" 
              roughness={0}
              reflectivity={1}
              metalness={1}
              />
            </mesh>
          ))}
          {innerParticles.map((particle, i) => (
            <mesh key={`inner-${i}`} position={particle}>
              <sphereGeometry args={[0.05, 16, 16]} />
              <meshStandardMaterial color="#672e2e" />
            </mesh>
          ))}


          {/* Background box */}
          <Box args={[50, 50, 50]} position={[0, 0, 0]}>
            <meshBasicMaterial attach="material" color="black" side={THREE.DoubleSide} />
          </Box>

          {/* Background plane */}
          {/* <Plane args={[100, 100]} position={[0, 0, -10]}>
            <meshBasicMaterial attach="material" color="black" side={THREE.DoubleSide} />
          </Plane> */}
        </group>
      </>
    );
};



