import React, { useState, useEffect } from 'react';
import Menu from './Menu'; 







/* Go to Description Anchor Animation */




const smoothScrollTo = (element) => {
  const targetPosition = element.getBoundingClientRect().top;
  const startPosition = window.pageYOffset;
  const distance = targetPosition - startPosition;
  const duration = 800; // Duration in milliseconds
  let startTime = null;

  const animation = (currentTime) => {
      if (startTime === null) startTime = currentTime;
      const timeElapsed = currentTime - startTime;
      const run = ease(timeElapsed, startPosition, distance, duration);
      window.scrollTo(0, run);
      if (timeElapsed < duration) requestAnimationFrame(animation);
  };

  const ease = (t, b, c, d) => {
      t /= d / 2;
      if (t < 1) return c / 2 * t * t + b;
      t--;
      return -c / 2 * (t * (t - 2) - 1) + b;
  };

  requestAnimationFrame(animation);
};

const scrollToDescription = () => {
  const element = document.querySelector('.DescContainerMain');
  if (element) {
      smoothScrollTo(element);
  }
};





/* ----------- */













const GoldClosingPrice = ({ backgroundImage }) => {
  const [openPrice, setOpenPrice] = useState('');
  const [highPrice, setHighPrice] = useState('');
  const [lowPrice, setLowPrice] = useState('');
  const [predictedClosePrice, setPredictedClosePrice] = useState(null);

  const executePrediction = async () => {
      if (!openPrice || !highPrice || !lowPrice) return;

      try {
          const payload = {
              Open: parseFloat(openPrice),
              High: parseFloat(highPrice),
              Low: parseFloat(lowPrice),
          };
          
          const response = await fetch(`${process.env.REACT_APP_API_URL_Classic}/predict_GoldClosingPrice`, {
              method: 'POST',
              headers: {
                  'Content-Type': 'application/json',
              },
              body: JSON.stringify(payload),
          });

          const data = await response.json();

          setPredictedClosePrice(data.predictedClose);
      } catch (error) {
          console.error("Erreur lors de la demande de prédiction:", error);
      }
    };

    useEffect(() => {
      window.scrollTo(0, 0);
    }, []);

    return (
      <div>
        <div className="BGImageContainer" style={{ backgroundImage: `url(${backgroundImage})` }}>
          <div>
            <Menu />
          </div>
          <div className="FirstContainer">
            <div className='CntFirstContainer'>
              <div className="PanelContainer">
                <div className="GoldPredictionResultContainer">
                  {predictedClosePrice ? (
                    <div><h3>Predicted Closing Price: {predictedClosePrice.toFixed(2)}&euro;</h3></div>
                  ) : (
                    <div className="placeholder">No Prediction Available Yet</div>
                  )}
                </div>
                <div className="InputsContainer">
                  <div className="GoldClosingPriceFormEl">
                    <label htmlFor="OpenPrice">Opening Price</label>
                    <input
                        type="number"
                        value={openPrice}
                        onChange={(e) => setOpenPrice(e.target.value)}
                        placeholder="1995"
                        id="OpenPrice"
                        name="OpenPrice"
                    />
                  </div>
                  <div className="GoldClosingPriceFormEl">
                    <label htmlFor="HighPrice">Highest Price</label>
                    <input
                        type="number"
                        value={highPrice}
                        onChange={(e) => setHighPrice(e.target.value)}
                        placeholder="2019.7"
                        id="HighPrice"
                        name="HighPrice"
                    />
                  </div>
                  <div className="GoldClosingPriceFormEl">
                    <label htmlFor="LowPrice">Lowest Price</label>
                    <input
                        type="number"
                        value={lowPrice}
                        onChange={(e) => setLowPrice(e.target.value)}
                        placeholder="1986.4"
                        id="LowPrice"
                        name="LowPrice"
                    />
                  </div>
                </div>
                <button className="gold-button" onClick={executePrediction}>
                    Predict Closing Price
                </button>  
              </div>
              <div className="DescRefContainer" onClick={scrollToDescription}>
                <p className="Clickable-text">Learn more about this project</p>
                <img src={`${process.env.PUBLIC_URL}/Multimedia/Anchor_logo/DescLogo.png`} alt="Logo" className="Clickable-logo" />
              </div>
            </div>
          </div>
        </div>
        <div className="DescContainerMain">
          <div className="DescContainer">
            <h6>Description</h6>
            <h5>This project was created using a Kaggle dataset to simulate a virtual asset manager helper. The purpose of this model is to predict the closing price of Gold using little information. <br /><br /><br />
              
              <span class="blurred">
                More details: Since the dataset was composed of dates and all needed amounts, little cleaning and pre-processing was necessary. Concerning the model, several approaches were explored during the development, 
                composed of deep learning algorithms and 'Grid Search CV' functions to explore possible machine learning algorithms. However, surprisingly or not, the most efficient option (taking into account performance and size) 
                was the easiest possible one, a simple linear regression. 'Cross Validation Score' tests were then conducted (both on train and test datasets) to ensure the results (including comparisons with 
                regularization techniques results), which did confirm the results we previously yielded (reporting a mean score of 99.95%).
              </span>
              
              <br /><br />
              The used dataset from Kaggle can be found <a href="https://www.kaggle.com/datasets/prajwaldongre/gold-futures-data-from-2012-2023?rvi=1" className="KaggleLink" target="_blank">here</a>.
            </h5>
          </div>
        </div>
      </div>
    );
  };

export default GoldClosingPrice;