const LoanDefault = ({ backgroundImage }) => {
  const [age, setAge] = useState('');
  const [income, setIncome] = useState('');
  const [loanAmount, setLoanAmount] = useState('');
  const [creditScore, setCreditScore] = useState('');
  const [monthsEmployed, setMonthsEmployed] = useState('');
  const [numCreditLines, setNumCreditLines] = useState('');
  const [interestRate, setInterestRate] = useState('');
  const [loanTerm, setLoanTerm] = useState('');
  const [dtiRatio, setDtiRatio] = useState('');
  const [education, setEducation] = useState('');
  const [employmentType, setEmploymentType] = useState('');
  const [maritalStatus, setMaritalStatus] = useState('');
  const [hasMortgage, setHasMortgage] = useState('');
  const [hasDependents, setHasDependents] = useState('');
  const [loanPurpose, setLoanPurpose] = useState('');
  const [hasCoSigner, setHasCoSigner] = useState('');

  const [predictedDefault, setPredictedDefault] = useState(null);
  const [confidencePercentage, setconfidencePercentage] = useState(null);
  const executePrediction = async () => {
    if (!age || !income || !loanAmount || !creditScore || !monthsEmployed || !numCreditLines || !interestRate || !loanTerm || !dtiRatio || !education || !employmentType || !maritalStatus || !hasMortgage || !hasDependents || !loanPurpose || !hasCoSigner) return;

      try {
        const payload = {
          Age: parseFloat(age),
          Income: parseFloat(income),
          LoanAmount: parseFloat(loanAmount),
          CreditScore: parseInt(creditScore, 10),
          MonthsEmployed: parseInt(monthsEmployed, 10),
          NumCreditLines: parseInt(numCreditLines, 10),
          InterestRate: parseFloat(interestRate),
          LoanTerm: parseInt(loanTerm, 10),
          DTIRatio: parseFloat(dtiRatio),
          Education: education,
          EmploymentType: employmentType,
          MaritalStatus: maritalStatus,
          HasMortgage: hasMortgage ? 'Yes' : 'No',
          HasDependents: hasDependents ? 'Yes' : 'No',
          LoanPurpose: loanPurpose,
          HasCoSigner: hasCoSigner ? 'Yes' : 'No'
        };
          
          const response = await fetch(`${process.env.REACT_APP_API_URL_Classic}/predict_loan_default`, {
              method: 'POST',
              headers: {
                  'Content-Type': 'application/json',
              },
              body: JSON.stringify(payload),
          });

          const data = await response.json();
          // console.log(data); // This will output the API response to the console

          setPredictedDefault(data.predictedDefault);
          setconfidencePercentage(data.confidencePercentage);
      } catch (error) {
          console.error("Erreur lors de la demande de prédiction:", error);
      }
    };

    useEffect(() => {
      window.scrollTo(0, 0);
    }, []);



    // Initial state object that tracks focus for all select inputs
    const [focusState, setFocusState] = useState({
      education: false,
      employmentType: false,
      maritalStatus: false,
      hasMortgage: false,
      hasDependents: false,
      loanPurpose: false,
      hasCoSigner: false
      // ... Add other fields as necessary
    });

    // Handler to set focus state for a given field
    const handleFocus = (field) => {
      setFocusState(prevState => ({ ...prevState, [field]: true }));
    };

    // Handler to unset focus state for a given field
    const handleBlur = (field) => {
      setFocusState(prevState => ({ ...prevState, [field]: false }));
    };

    return (
      <div>
        <div className="BGImageContainer" style={{ backgroundImage: `url(${backgroundImage})` }}>
          <div>
            <Menu />
          </div>
          <div className="FirstContainer">
            <div className='CntFirstContainer'>
              <div className="PanelContainerRD">
                <div className="GoldPredictionResultContainer">
                  {predictedDefault !== null ? (
                    <>
                      <div><h3>Predicted Default Risk: {predictedDefault ? 'High' : 'Low'}</h3></div>
                      {confidencePercentage && (
                        <div><h4>Confidence: {confidencePercentage }</h4></div> // Format the confidence as a percentage
                      )}
                    </>
                  ) : (
                    <div className="placeholder">No Prediction Available Yet</div>
                  )}
                </div>
                <div className="LoanDefaultInputsContainer">
                  {/* Age */}
                  <div className="LoanDefaultFormElement">
                    <input type="number" value={age} onChange={(e) => setAge(e.target.value)} placeholder="25" id="age" required />
                    <label htmlFor="age" className='label'>Age</label>
                  </div>
                  {/* Income */}
                  <div className="LoanDefaultFormElement">
                    <input type="number" value={income} onChange={(e) => setIncome(e.target.value)} placeholder="100000" id="income" required />
                    <label htmlFor="income" className='label'>Annual income</label>
                  </div>
                  {/* Loan Amount */}
                  <div className="LoanDefaultFormElement">
                    <input type="number" value={loanAmount} onChange={(e) => setLoanAmount(e.target.value)} placeholder="25000" id="loanAmount" required />
                    <label htmlFor="loanAmount" className='label'>Loan Amount</label>
                  </div>
                  {/* Credit Score */}
                  <div className="LoanDefaultFormElement">
                    <input type="number" value={creditScore} onChange={(e) => setCreditScore(e.target.value)} placeholder="0 ≤ x ≤ 1000" id="creditScore" required />
                    <label htmlFor="creditScore" className='label'>Credit Score</label>
                  </div>
                  {/* Months Employed */}
                  <div className="LoanDefaultFormElement">
                    <input type="number" value={monthsEmployed} onChange={(e) => setMonthsEmployed(e.target.value)} placeholder="80" id="monthsEmployed" required />
                    <label htmlFor="monthsEmployed" className='label'>Months Employed</label>
                  </div>
                  {/* Number of Credit Lines */}
                  <div className="LoanDefaultFormElement">
                    <input type="number" value={numCreditLines} onChange={(e) => setNumCreditLines(e.target.value)} placeholder="3" id="numCreditLines" required />
                    <label htmlFor="numCreditLines" className='label'>Number of Credit Lines</label>
                  </div>
                  {/* Interest Rate */}
                  <div className="LoanDefaultFormElement">
                    <input type="number" value={interestRate} onChange={(e) => setInterestRate(e.target.value)} placeholder="10" id="interestRate" required />
                    <label htmlFor="interestRate" className='label'>Interest Rate</label>
                  </div>
                  {/* Loan Term */}
                  <div className="LoanDefaultFormElement">
                    <input type="number" value={loanTerm} onChange={(e) => setLoanTerm(e.target.value)} placeholder="36" id="loanTerm" required />
                    <label htmlFor="loanTerm" className='label'>Loan Term</label>
                  </div>
                  {/* DTI Ratio */}
                  <div className="LoanDefaultFormElement">
                    <input type="number" value={dtiRatio} onChange={(e) => setDtiRatio(e.target.value)} placeholder="25" id="dtiRatio" required />
                    <label htmlFor="dtiRatio" className='label'>DTI Ratio</label>
                  </div>
                  {/* Education */}
                  <div className="LoanDefaultFormBoxElement">
                    <select
                      value={education}
                      onChange={(e) => setEducation(e.target.value)}
                      id="education"
                      onFocus={() => handleFocus('education')}
                      onBlur={() => handleBlur('education')}
                      data-value={education || ''}
                      required
                      className={!education ? 'placeholder' : ''}
                    >
                      <option value="">Select Education</option>
                      <option value="High School">High School</option>
                      <option value="Bachelor's">Bachelor's</option>
                      <option value="Master's">Master's</option>
                      <option value="PhD">PhD</option>
                    </select>
                    <label htmlFor="education" className={focusState.education || education ? 'label raise' : 'label'}>
                      Education
                    </label>
                  </div>



                  {/* Employment Type */}
                  <div className="LoanDefaultFormBoxElement">
                    <select
                      value={employmentType}
                      onChange={(e) => setEmploymentType(e.target.value)}
                      id="employmentType"
                      onFocus={() => handleFocus('employmentType')}
                      onBlur={() => handleBlur('employmentType')}
                      data-value={employmentType || ''}
                      required
                      className={!employmentType ? 'placeholder' : ''}
                    >
                      <option value="">Select Employment Type</option>
                      <option value="Unemployed">Unemployed</option>
                      <option value="Part-time">Part-time</option>
                      <option value="Self-employed">Self-employed</option>
                      <option value="Full-time">Full-time</option>
                    </select>
                    <label htmlFor="employmentType" className={focusState.employmentType || employmentType ? 'label raise' : 'label'}>
                      Employment Type
                    </label>
                  </div>

                  {/* Marital Status */}
                  <div className="LoanDefaultFormBoxElement">
                    <select 
                      value={maritalStatus} 
                      onChange={(e) => setMaritalStatus(e.target.value)} 
                      id="maritalStatus"
                      onFocus={() => handleFocus('maritalStatus')}
                      onBlur={() => handleBlur('maritalStatus')}
                      data-value={maritalStatus || ''}
                      required
                      className={!maritalStatus ? 'placeholder' : ''}
                    >
                      <option value="">Select Marital Status</option>
                      <option value="Single">Single</option>
                      <option value="Married">Married</option>
                      <option value="Divorced">Divorced</option>
                    </select>
                    <label htmlFor="maritalStatus" className={focusState.maritalStatus || maritalStatus ? 'label raise' : 'label'}>Marital Status</label>
                  </div>

                  {/* Has Mortgage */}
                  <div className="LoanDefaultFormBoxElement">
                    <select 
                      value={hasMortgage} 
                      onChange={(e) => setHasMortgage(e.target.value)} 
                      id="hasMortgage"
                      onFocus={() => handleFocus('hasMortgage')}
                      onBlur={() => handleBlur('hasMortgage')}
                      data-value={hasMortgage || ''}
                      required
                      className={!hasMortgage ? 'placeholder' : ''}
                    >
                      <option value="">Select Option</option>
                      <option value="Yes">Yes</option>
                      <option value="No">No</option>
                    </select>
                    <label htmlFor="hasMortgage" className={focusState.hasMortgage || hasMortgage ? 'label raise' : 'label'}>Has Mortgage</label>
                  </div>

                  {/* Has Dependents */}
                  <div className="LoanDefaultFormBoxElement">
                    <select 
                      value={hasDependents} 
                      onChange={(e) => setHasDependents(e.target.value)} 
                      id="hasDependents"
                      onFocus={() => handleFocus('hasDependents')}
                      onBlur={() => handleBlur('hasDependents')}
                      data-value={hasDependents || ''}
                      required
                      className={!hasDependents ? 'placeholder' : ''}
                    >
                      <option value="">Select Option</option>
                      <option value="Yes">Yes</option>
                      <option value="No">No</option>
                    </select>
                    <label htmlFor="hasDependents" className={focusState.hasDependents || hasDependents ? 'label raise' : 'label'}>Has Dependents</label>
                  </div>

                  {/* Loan Purpose */}
                  <div className="LoanDefaultFormBoxElement">
                    <select 
                      value={loanPurpose} 
                      onChange={(e) => setLoanPurpose(e.target.value)} 
                      id="loanPurpose"
                      onFocus={() => handleFocus('loanPurpose')}
                      onBlur={() => handleBlur('loanPurpose')}
                      data-value={loanPurpose || ''}
                      required
                      className={!loanPurpose ? 'placeholder' : ''}
                    >
                      <option value="">Select Loan Purpose</option>
                      <option value="Personal">Personal</option>
                      <option value="Business">Business</option>
                      <option value="Education">Education</option>
                      <option value="Home">Home</option>
                      <option value="Other">Other</option>
                    </select>
                    <label htmlFor="loanPurpose" className={focusState.loanPurpose || loanPurpose ? 'label raise' : 'label'}>Loan Purpose</label>
                  </div>

                  {/* Has CoSigner */}
                  <div className="LoanDefaultFormBoxElement">
                    <select 
                      value={hasCoSigner} 
                      onChange={(e) => setHasCoSigner(e.target.value)} 
                      id="hasCoSigner"
                      onFocus={() => handleFocus('hasCoSigner')}
                      onBlur={() => handleBlur('hasCoSigner')}
                      data-value={hasCoSigner || ''}
                      required
                      className={!hasCoSigner ? 'placeholder' : ''}
                    >
                      <option value="">Select Option</option>
                      <option value="Yes">Yes</option>
                      <option value="No">No</option>
                    </select>
                    <label htmlFor="hasCoSigner" className={focusState.hasCoSigner || hasCoSigner ? 'label raise' : 'label'}>Has Cosigner</label>
                  </div>
                </div>
                <button className="gold-button" onClick={executePrediction}>
                  Predict Default Risk
                </button>
              </div>
              <div className="DescRefContainer" onClick={scrollToDescription}>
                <p className="Clickable-text">Learn more about this project</p>
                <img src={`${process.env.PUBLIC_URL}/Multimedia/Anchor_logo/DescLogo.png`} alt="Logo" className="Clickable-logo" />
              </div>
            </div>
          </div>
        </div>
        <div className="DescContainerMain">
          <div className="DescContainer">
            <h6>Description</h6>
            <h5>This project was created using a Kaggle dataset to simulate a banking risk asset manager virtual assistant. 
              The purpose of this model is to compare predicted probabilities of loan payment defaults of the bank's largest clients using internal listings. 
              The Bank taken as an example here already uses a credit score (calculated by the bank’s own AI model which was approved by the European Central Bank) for a proper evaluation of risks in the company's particular operational sector. 
              This credit score then becomes a key feature to correctly compare the multiple important loans (in terms of value), and not only assess the risk with a simple credit score value anymore. <br /><br /><br />

              <span class="blurred">
                More details: After having cleaned up the dataset and treated strings (of course treating nominal and ordianal values differently and appropriately), typical statistical analysis was conducted to treat data further. However, one observation was more than obvious, 
                as usual in churn rate analysis and similar tasks, there was an important imbalance between the large number of records registered for the 'No Default' category 
                compared to the very small number of records for the opposite category ('Default'). Knowing that the minority class only stood for 11.5% of the total dataset size and that it 
                would surely lead us to very poor results in the most concerning category, different techniques were tested to tackle the imbalance such as 'Under-sampling', 'Oversampling' using 'SMOTE' 
                and ensemble learning, a deep learning algorithm was used and detailed metrics analysis was carried out to compare the results. The most efficient one was determined to be the oversampling method using 'SMOTE'. 
                Now that the dataset was ready, a lot of different approaches had to be tested, some of which included: a fine-tuned deep learning model, tree classifiers, unsupervised models 
                (Gaussian and Multinomial naive bayes), 'K neighbours' classifier, 'SVC', bagging Classifier, etc. After further evaluations, the random forest classifier appeared to be the most efficient model 
                (with an F1- Score of around 95% for both categories and satisfying precision and recall results). Small parenthesis aside, there is probably no need to explain that, for this project, no PCA (Principal Component Analysis) 
                or other feature engineering techniques were used to correctly fulfil the bank's demands on the project, which include their willingness to use all the given inputs of the dataset to build the model.   
                <br /><br />
              </span>

              The used dataset from Kaggle can be found <a href="https://www.kaggle.com/datasets/nikhil1e9/loan-default" className="KaggleLink" target="_blank">here</a>.
            </h5>
          </div>
        </div>
      </div> 
    );
  };

export default LoanDefault;