import React, { useEffect, useState } from 'react';
import { HashRouter as Router, Route, Routes } from 'react-router-dom';
import { isMobile, isTablet } from 'react-device-detect';
import Home from './Home';
import More from './More';
import QualityControl from './QualityControl';
import GoldClosingPrice from './GoldClosingPrice';
import LoanDefault from './LoanDefault';
import RegulatoryExpert from './RegulatoryExpert';
import PosePrediction from './PosePrediction';
import AugmentdWorkspace from './AugmentedWorkspace';
import LoadingAnimation from './LoadingAnimation';
import License from './License';

const App = () => {

  
/*LoadingAnimation*/
// Initially set isLoading to true to show the loading animation
 // Assume the app is loading and in standalone mode initially
  const [isLoading, setIsLoading] = useState(window.matchMedia('(display-mode: standalone)').matches);

  useEffect(() => {
    const firstLaunchKey = 'isFirstLaunch';
    let isFirstLaunch = localStorage.getItem(firstLaunchKey) === null;

    if (window.matchMedia('(display-mode: standalone)').matches) {
      // Adjust loading time based on whether it's the first launch
      // const loadingDuration = isFirstLaunch ? 13000 : 5000;
      const loadingDuration = isFirstLaunch && (isMobile || isTablet) ? 15000 : 5000;

      setTimeout(() => {
        setIsLoading(false);

        // Update local storage to indicate the app has been launched before
        if (isFirstLaunch) {
          localStorage.setItem(firstLaunchKey, 'no');
        }
      }, loadingDuration);
    } else {
      // Ensure loading state is immediately false if not in standalone mode
      setIsLoading(false);
    }

    if ('serviceWorker' in navigator) {
      navigator.serviceWorker.register(`${process.env.PUBLIC_URL}/service-worker.js`)
        .then(registration => console.log('SW registered: ', registration))
        .catch(registrationError => console.log('SW registration failed: ', registrationError));
    }
  }, []);
 



/* ----------- */











/* PWA Notif */

 // This state will store whether the PWA is already installed
 const [isPwaInstalled, setIsPwaInstalled] = useState(false);
 const [deferredPrompt, setDeferredPrompt] = useState(null);

 useEffect(() => {
   // Check if the app is running in standalone mode
   setIsPwaInstalled(window.matchMedia('(display-mode: standalone)').matches);

   // Add event listener for PWA install prompt
   window.addEventListener('beforeinstallprompt', (e) => {
     // Prevent Chrome 67 and earlier from automatically showing the prompt
     e.preventDefault();
     // Save the event so it can be triggered later.
     setDeferredPrompt(e);
   });

   // Show install prompt only on first visit and if PWA is not installed
   const isFirstVisit = localStorage.getItem('isFirstVisit') === null;
   if (isFirstVisit && !isPwaInstalled) {
     localStorage.setItem('isFirstVisit', 'no');
     showInstallPromotion();
     console.log("Notif should appear!")
   }
 }, [isPwaInstalled]);

 const showInstallPromotion = () => {
   if (deferredPrompt) {
     deferredPrompt.prompt();
     // Wait for the user to respond to the prompt
     deferredPrompt.userChoice.then((choiceResult) => {
       if (choiceResult.outcome === 'accepted') {
         console.log('User accepted the install prompt');
       } else {
         console.log('User dismissed the install prompt');
       }
       setDeferredPrompt(null);
     });
   }
 };


/* ----------- */










/*Warm up*/

  useEffect(() => {
    fetch(`${process.env.REACT_APP_API_URL_Classic}/ping`)
      .then(response => {
        const status = response.status;
        response.text().then(text => {
          console.log('Warming up the server:', status, 'Server Response:', text);
        });
        return response;
      })
      .catch(error => console.error('Error warming up the server:', error));
  }, []);


  useEffect(() => {
    fetch(`${process.env.REACT_APP_API_URL_Pose_Pred}/ping`)
      .then(response => {
        const status = response.status;
        response.text().then(text => {
          console.log('Warming up the pose prediction server:', status, 'Pose Prediction Server Response:', text);
        });
        return response;
      })
      .catch(error => console.error('Error warming up the pose prediction server:', error));
  }, []);
  

  /* "200" => "OK", "404" => "Not Found", "500" => "Internal Server Error" */

  /*End of Warm up*/
  /* basename="/Projects_Showcase"   only with Browser instead of HashRouter*/


/* ----------- */

  return (
    <Router basename="/">
      {isLoading ? (
        <LoadingAnimation />
      ) : (
        <div>
          <Routes>
            <Route path="/" element={<Home backgroundImage={`${process.env.PUBLIC_URL}/Multimedia/Backgrounds/Home_Wallpaper.png`} showInstallPromotion={showInstallPromotion} />} />
            <Route path="/More" element={<More backgroundImage={`${process.env.PUBLIC_URL}/Multimedia/Backgrounds/Home_Wallpaper.png`} />} />
            <Route path="/QualityControl" element={<QualityControl backgroundImage={`${process.env.PUBLIC_URL}/Multimedia/Backgrounds/QualityControl_Wallpaper.png`} />} />
            <Route path="/GoldClosingPrice" element={<GoldClosingPrice backgroundImage={`${process.env.PUBLIC_URL}/Multimedia/Backgrounds/GoldClosingPrice_Wallpaper.png`} />} />
            <Route path="/LoanDefault" element={<LoanDefault backgroundImage={`${process.env.PUBLIC_URL}/Multimedia/Backgrounds/LoanDefault_Wallpaper.png`} />} />
            <Route path="/PosePrediction" element={<PosePrediction backgroundImage={`${process.env.PUBLIC_URL}/Multimedia/Backgrounds/PosePred_Wallpaper.png`} />} />
            <Route path="/AugmentedWorkspace" element={<AugmentdWorkspace backgroundImage={`${process.env.PUBLIC_URL}/Multimedia/Backgrounds/AugmentedWorkspace_Wallpaper.png`} />} />
            <Route path="/License" element={<License />} />
          </Routes>
        </div>
      )}
    </Router>
  );
};
/*<Route path="/RegulatoryExpert" element={<RegulatoryExpert backgroundImage={`${process.env.PUBLIC_URL}/LoanDefault_Wallpaper.png`} />} />*/
export default App;