import React, { useState, useRef, useEffect} from 'react';
import Menu from './Menu'; 







/* Go to Description Anchor Animation */




const smoothScrollTo = (element) => {
  const targetPosition = element.getBoundingClientRect().top;
  const startPosition = window.pageYOffset;
  const distance = targetPosition - startPosition;
  const duration = 800; // Duration in milliseconds
  let startTime = null;

  const animation = (currentTime) => {
      if (startTime === null) startTime = currentTime;
      const timeElapsed = currentTime - startTime;
      const run = ease(timeElapsed, startPosition, distance, duration);
      window.scrollTo(0, run);
      if (timeElapsed < duration) requestAnimationFrame(animation);
  };

  const ease = (t, b, c, d) => {
      t /= d / 2;
      if (t < 1) return c / 2 * t * t + b;
      t--;
      return -c / 2 * (t * (t - 2) - 1) + b;
  };

  requestAnimationFrame(animation);
};

const scrollToDescription = () => {
  const element = document.querySelector('.DescContainerMain');
  if (element) {
      smoothScrollTo(element);
  }
};





/* ----------- */













const PosePrediction = ({ backgroundImage }) => {
  const videoRef = useRef(null);
  const [streaming, setStreaming] = useState(false);
  const canvasRef = useRef(null); // Reference to the canvas element

  const captureFrame = () => {
    if (!streaming || !videoRef.current) return;
  
    // Create a new canvas element each time
    const canvas = document.createElement('canvas');
    canvas.width = videoRef.current.videoWidth;
    canvas.height = videoRef.current.videoHeight;
    const context = canvas.getContext('2d');
  
     // Flip the context horizontally
    context.save(); // Save the current state
    context.scale(-1, 1); // Flip horizontally
    context.translate(-canvas.width, 0); // Offset the flip


    // Draw the current frame from video onto the canvas
    context.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
  
     // Restore the context to its original state
    context.restore();

    // Convert the canvas content to a Blob and send it for prediction
    canvas.toBlob(sendFrameForPrediction, 'image/jpeg');
  };

  useEffect(() => {
    let intervalId;
    if (streaming) {
      intervalId = setInterval(captureFrame, 200); // Capture every second
    }
    return () => clearInterval(intervalId); // Cleanup on unmount or stop
  }, [streaming]);


  const startVideo = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true });
      videoRef.current.srcObject = stream;
      videoRef.current.play(); // Ensure the video plays
      setStreaming(true);
    } catch (error) {
      console.error("Error accessing webcam:", error);
    }
  };
  

  const stopVideo = () => {
    if (videoRef.current && videoRef.current.srcObject) {
      videoRef.current.srcObject.getTracks().forEach(track => track.stop());
      setStreaming(false);
    }
  };

  const sendFrameForPrediction = async (blob) => {
    try {
      const formData = new FormData();
      // Append a timestamp to the filename to ensure uniqueness
      const filename = 'frame-' + new Date().getTime() + '.jpg';
      formData.append('file', blob, filename);
      
      const response = await fetch(`${process.env.REACT_APP_API_URL_Pose_Pred}/predict_pose`, {
        method: 'POST',
        body: formData,
      });
      if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);
      
      const imageBlob = await response.blob();
      // Log the Blob type to confirm it's being created correctly
      // console.log('Captured Blob:', blob);

      // Log the size of the Blob as a sanity check
      // console.log('Captured Blob size:', blob.size);
      const imageUrl = URL.createObjectURL(imageBlob);
      const image = new Image();
      image.onload = () => {
        const ctx = canvasRef.current.getContext('2d');
        ctx.drawImage(image, 0, 0, canvasRef.current.width, canvasRef.current.height);
        URL.revokeObjectURL(imageUrl); // Clean up the URL object
      };
      image.src = imageUrl;
  
    } catch (error) {
      console.error("Error during prediction:", error);
    }
  };

  useEffect(() => {
    window.scrollTo(0, 0);
  }, []);

  return (
    <div>
      <div className="BGImageContainer" style={{ backgroundImage: `url(${backgroundImage})` }}>
        <div>
          <Menu />
        </div>
        <div className="FirstContainer">
          <div className='CntFirstContainer'>
            <div className="PanelContainerRD">
              <div className="WebcamPanel"> 
                {/* <video ref={videoRef} autoPlay hidden={!streaming}></video> */}
                <video ref={videoRef} style={{ display: 'none' }}></video> {/* Hide the video element */}
                {/* Canvas element for displaying predictions */}
                <canvas ref={canvasRef} className='PosePredCanv'></canvas>
              </div>
              {!streaming && (
                <button className="gold-button" onClick={startVideo}>Start Webcam</button>
              )}
              {streaming && (
                <button className="gold-button" onClick={stopVideo}>Stop Webcam</button>
              )}
              
            </div>
            <div className="DescRefContainer" onClick={scrollToDescription}>
              <p className="Clickable-text">Learn more about this project</p>
              <img src={`${process.env.PUBLIC_URL}/Multimedia/Anchor_logo/DescLogo.png`} alt="Logo" className="Clickable-logo" />
            </div>
          </div>
        </div>
      </div>
      <div className="DescContainerMain">
        <div className="DescContainer">
          <h6>Description</h6>
          <h5>The goal of this project was not to create complicated technology but rather use the currently
            accessible one to create a complete service. The end goal here is to demonstrate the
            possibility to unlock instant teleportation abilities around the world with a simple click on a
            computer. This service would for example allow a doctor to perform urgent and vital surgeries
            and give all types of care in very remote regions of the world where no other
            professionals can arrive in time. In a simpler way, this technology could also help representatives attend
            multiple international conventions and meetings without having to travel, limiting the time
            necessary to attend this type of event, and also contributing to decreasing carbon footprint
            (which usually tends to increase a lot when calculating all ‘necessary’ CO2 emissions of such
            business trips). Professionals could now physically interact with other professionals or their
            clients in real-time, no matter the location.<br /><br /><br />
            
            <span class="blurred">
              More details: This webpage contains a simple YOLOv8 Pose model to detect the person’s
              skeleton (including category name, confidence and bounding boxes). The ‘yolov8n-pose’
              model was precisely chosen to ensure quick inference on a webpage (using CPU). A real
              approach would benefit from using GPUs (Tesla microarchitecture from NVIDIA, TPUs or any
              other tensor-based architecture processing units) as well as the ‘yolo_nas_pose_l’ model
              (from Deci.ai, using “Super Gradients”). The current time-frame is limited to 5fps to ensure
              access of the demo to everyone on every type of device, but using the real-time approach, as
              detailed earlier, would allow a fluency of more than a 100fps (latency of less of around 9ms
              per snapshot) to ensure fluid skeleton inference where very precise movements are made,
              even though a commercialised version should probably be limited to smoothen movements
              using interpolation or other similar mechanisms to ensure always correspondent movements
              (preventing unwanted gestures).<br /><br />
              
              Since this website serves a demonstration purpose, as already mentioned, images used for
              inference are rendered alongside results; a commercialised version would only serve results.
              These results will then be transmitted to a humanoid robot (such as Tesla’s Optimus Gen 2,
              BMW’s Figure 01, Boston Dynamics’ Atlas, etc), hosted somewhere in the world in a secured
              warehouse and rented for the using time, with consequent additional costs, or already
              owned by one’s, wherever it is stored (even when taken in a faraway place for expeditions,
              humanitarian assistance missions, etc), so that it mimics the exact user’s movements. Simple
              VR locomotion platform would also be used to ease displacement. Robot vision camera feed
              will of course be transmitted to users, as well as user’s audio being transmitted to the robot
              (both simple audio clip, triggered by a voice command, or transcription and oral
              re-transcription, including translation if needed, triggered the same way, approaches can be
              explored and proposed) to ensure full perception for users. An adjustment of skeleton
              landmarks orginal structure of the YOLO model is needed based on the robot model elected
              to propose this service.
            </span>
          </h5>
        </div>
      </div>
    </div>
  );
};
export default PosePrediction;